## Hata riskinin düzey sözcüğü: göstergenin üçte birlik dilimleri.
func _risk_word(risk: float) -> String:
	return tr(RISK_KEYS[mini(int(risk * RISK_KEYS.size()), RISK_KEYS.size() - 1)])


## Planlamada üstüne gelince görünen "→" ve "×": satırın bilgi sütununun sağ üstünde, efor sayısının üstünde.
func _keys(kinds: Array) -> Control:
	_acts = SprintUiShared.row_keys(kinds, String(card.id), action.emit)
	_acts.size_flags_horizontal = Control.SIZE_SHRINK_BEGIN
	_acts.size_flags_vertical = Control.SIZE_SHRINK_BEGIN
	# Panelin sağ kenarı bilgi sütununun sağ kenarından `SPACE_M + SPACE_XXS` içeride, üstü satırın üstünden `SPACE_XS` aşağıda.
	var keys_w: int = kinds.size() * UiTokens.D_H_KEY_SM + (kinds.size() + 1) * UiTokens.SPACE_XXS
	var holder := SprintUiShared.pad(_acts, Vector4i(UiTokens.D_W_CARD_INFO - UiTokens.SPACE_M - UiTokens.SPACE_XXS - keys_w,
		UiTokens.SPACE_XS, 0, 0))
	holder.mouse_filter = Control.MOUSE_FILTER_IGNORE
	return holder


# --- Zaman ekseni ---------------------------------------------------------------------------

func _x(week: float) -> float:
	return roundf(week * UiTokens.D_W_TIMELINE / UiTokens.D_TIMELINE_WEEKS)


## Kartın aşamaları eksende: bekleme noktalı çizgisi, çubuk, sprint dışına kalan pay ve PM'in gölgesi. Eksenden önce ya da önden
## bitmiş aşama çizilmez: art arda bitenler tek tik kutusudur, son bitenin renginde, sonraki çubuğun başına takılır (arkasında çubuk
## yoksa tek başına). Sprint dışına kalan paylar arka arkaya durur: sonraki aşamanın payı öncekinin bittiği yerden başlar, eksenin
## sonunda kesilir.
func _lane(h: int) -> Control:
	var lane := Control.new()
	lane.custom_minimum_size = Vector2(UiTokens.D_W_TIMELINE, h)
	lane.size_flags_vertical = Control.SIZE_SHRINK_CENTER
	lane.mouse_filter = Control.MOUSE_FILTER_IGNORE
	var top: float = (h - UiTokens.D_H_STAGE_BAR) / 2.0
	var shadows: Array = []
	var waits: Array = []
	var bars: Array = []
	var ticks: Array = []
	var out_end := 0.0
	for s: Dictionary in card.stages:
		if SprintUiShared.stage_done(s):
			ticks.append(s)
			continue
		for wait: Dictionary in s.waits:
			var from: float = _x(wait.from)
			var width: float = _x(minf(wait.to, UiTokens.D_TIMELINE_WEEKS)) - from
			if width >= 1.0:
				var gap: StagePaint = StagePaint.part(&"wait", s.stage, {"from": wait.from, "to": wait.to, "person": wait.person, "role": wait.role},
					Rect2(from, top + (UiTokens.D_H_STAGE_BAR - UiTokens.D_H_WAIT) / 2.0, width, UiTokens.D_H_WAIT))
				gap.tooltip_text = _wait_tip(wait)
				waits.append(gap)
		if s.start >= 0.0:
			var left: float = _x(s.start)
			bars.append(_bar(s, Rect2(left, top, maxf(_x(s.end) - left, UiTokens.D_W_STAGE_BAR_LEAST), UiTokens.D_H_STAGE_BAR), "in", ticks))
			ticks = []
			var shade: StagePaint = _shadow(s, top)
			if shade != null:
				shadows.append(shade)
		if s.out_from >= 0.0:
			var out_left: float = maxf(_x(s.out_from), out_end)
			var out_right: float = minf(out_left + _x(s.out_to) - _x(s.out_from), UiTokens.D_W_TIMELINE)
			if out_right - out_left >= 1.0:
				bars.append(_bar(s, Rect2(out_left, top, out_right - out_left, UiTokens.D_H_STAGE_BAR), "out", ticks))
				ticks = []
				out_end = out_right
	if not ticks.is_empty():
		bars.append(_tick(ticks, Rect2(0.0, top, UiTokens.D_W_TICK_BOX, UiTokens.D_H_STAGE_BAR)))
	for part: Control in shadows + waits + bars:
		lane.add_child(part)
	if _ctx.mode == "active":
		set_now(_ctx.now)
	return lane


## Art arda biten aşamaların tek tik kutusu, son bitenin renginde; ipucu hangi aşamaların bittiğini satır satır yazar.
func _tick(ticks: Array, rect: Rect2) -> StagePaint:
	var box: StagePaint = StagePaint.part(&"tick", ticks.back().stage, {}, rect)
	box.tooltip_text = "\n".join(ticks.map(func(s: Dictionary) -> String:
		return SprintUiShared.SEP.join([SprintUiShared.stage_name(s.stage), SprintUiShared.done_text(s)])))
	return box


## Bir aşamanın çubuğu: zemini, bitmiş aşamaların tik kutusu (`ticks`, art arda bitenler), görüşme taramaları, ikon ve sayı,
## çalışanların yüzleri. `piece` "in" sprintin içindeki çubuk, "out" sprint dışına kalan pay.
func _bar(s: Dictionary, rect: Rect2, piece: String, ticks: Array) -> StagePaint:
	var running: bool = _ctx.mode == "active"
	var candidate: bool = _ctx.candidate
	var out: bool = piece == "out"
	var state: String = "ghost" if candidate else ("out" if out else "plan")
	var total: float = s.pre + s.need
	var main: String = str(roundi(s.out if out else s.in_sprint - s.done0))
	var sub := ""
	var fill := 0.0
	if not out and s.pre > SprintSystem.EPS and not running:
		main = str(roundi(s.pre))
		sub = "/%d" % roundi(total)
		fill = s.pre / total
	var bar: StagePaint = StagePaint.part(&"bar", s.stage, {"state": state, "late": card.late, "fill": fill,
		"from": s.out_from if out else s.start, "to": s.out_to if out else s.end, "piece": piece}, rect)
	bar.clip_contents = true
	if candidate:
		bar.modulate.a = UiTokens.D_GHOST_ALPHA
	if not ticks.is_empty():
		bar.add_child(_tick(ticks, Rect2(0.0, 0.0, UiTokens.D_W_TICK_BOX, rect.size.y)))
	if not out and not candidate:
		for m: Dictionary in s.meet:
			var from: float = maxf(_x(m.from), rect.position.x)
			var to: float = minf(_x(m.to), rect.end.x)
			if to - from >= 1.0:
				var scan: StagePaint = StagePaint.part(&"meet", s.stage, m, Rect2(from - rect.position.x, 0.0, to - from, rect.size.y))
				scan.tooltip_text = "\n".join(SprintUiShared.meet_lines(m.kinds))
				bar.add_child(scan)
	var left: float = UiTokens.D_W_TICK_BOX + UiTokens.SPACE_S if not ticks.is_empty() else float(UiTokens.D_STAGE_BAR_PAD.x)
	var label: StagePaint = StagePaint.part(&"label", s.stage, {"state": state, "late": card.late, "main": main, "sub": sub, "left": left,
		"room": 0.0, "icon": SprintUiShared.stage_icon(s.stage)}, Rect2(Vector2.ZERO, rect.size))
	bar.add_child(label)
	var faces := SprintUiShared.box(-UiTokens.SPACE_S)
	faces.mouse_filter = Control.MOUSE_FILTER_IGNORE
	bar.add_child(faces)
	var entry := {"ground": bar, "label": label, "faces": faces, "stage": s, "out": out, "left": left, "main": main, "sub": sub, "work": main}
	bar.tip = _bar_tip.bind(entry)
	if running and not out:
		entry["workers"] = _workers(s)
		_live.append(entry)
	elif not running and not out and not candidate:
		_founder_face(entry)
	return bar


## Çubuğun ipucu, açılırken okunur: "{aşama} · efor {n}" ve durum parçaları: önden yapılan pay, hazırlanmasaydı efor, sprint dışına
## kalan pay, çalışanlar (koşarken o an çalışanlar); sprintin içindeki çubukta kurucunun görüşme kalemleri ayrı satırlarda.
func _bar_tip(entry: Dictionary) -> String:
	var s: Dictionary = entry.stage
	var out: bool = entry.out
	var total: float = s.pre + s.need
	var effort: String = str(roundi(s.out if out else total))
	var working: Array = []
	if _ctx.mode == "active" and not out:
		working = entry.workers.filter(func(w: Dictionary) -> bool: return w.from <= _now and _now < w.to).map(
			func(w: Dictionary) -> String: return w.id)
		if s.start - SprintSystem.EPS <= _now and _now < s.end - SprintSystem.EPS:
			effort = "%d/%d" % [floori(s.pre + SprintTimeline.done_at(s, _now) + SprintSystem.EPS), roundi(total)]
	var parts: PackedStringArray = [SprintUiShared.stage_name(s.stage), SprintUiShared.effort_tip(effort)]
	if not out and s.pre > SprintSystem.EPS:
		parts.append(tr("PRODUCT_STAGE_READY").format({"pct": Fmt.percent(s.pre / total * 100.0, 0)}))
	if card.pm != null and s.need_raw > s.need + SprintSystem.EPS:
		parts.append(tr("PRODUCT_STAGE_RAW").format({"n": roundi(s.need_raw)}))
	if out:
		parts.append(tr("PRODUCT_STAGE_OUT"))
	if not working.is_empty():
		parts.append(tr("PRODUCT_STAGE_NOW").format({"names": ", ".join(_names(working))}))
	elif not s.people.is_empty():
		parts.append(", ".join(_names(s.people)))
	var lines: PackedStringArray = [SprintUiShared.SEP.join(parts)]
	if not out:
		lines.append_array(SprintUiShared.meet_lines_of([s]))
	return "\n".join(lines)


## Kişilerin tam adları (aynı adlı iki kişi böyle ayrılır).
func _names(ids: Array) -> Array:
	return ids.map(func(id: String) -> String: return CharacterRegistry.get_character(id).character_name)


## Beklemenin ipucu: kimi beklediği ve o kişi o an hangi kartın hangi aşamasındaysa ("Bekliyor: Ayşe Kaya (Fatura · Geliştirme)");
## aşamada kimse yoksa rolün çoğulu (araştırmada ürün yöneticisi ya da kurucu).
func _wait_tip(wait: Dictionary) -> String:
	if wait.person == "":
		return tr(WAIT_KEYS[wait.role])
	var who: String = CharacterRegistry.get_character(wait.person).character_name
	if not wait.busy.is_empty():
		who += " (" + SprintUiShared.SEP.join([SprintCatalog.card_name(SprintCatalog.card_by_id(wait.busy.card)),
			SprintUiShared.stage_name(wait.busy.stage)]) + ")"
	return tr("PRODUCT_WAIT_FOR").format({"name": who})


## PM'in kısalttığı payın gölgesi: çubuğun altında, çubuğun başından hazırlanmasaydı biteceği yere uzanan şerit. Hazırlanmamış
## hâlin ek süresi, ek işin son parçanın hızına bölünmesidir.
func _shadow(s: Dictionary, top: float) -> StagePaint:
	if card.pm == null or s.need_raw <= s.need + SprintSystem.EPS or s.pieces.is_empty():
		return null
	var last: Dictionary = s.pieces[-1]
	var pace: float = float(last.work) / maxf(last.to - last.from, SprintSystem.EPS)
	var from: float = _x(s.pieces[0].from)
	var to: float = minf(_x(float(last.to) + (s.need_raw - s.need) / pace), UiTokens.D_W_TIMELINE)
	if to - from < 1.0:
		return null
	var shade: StagePaint = StagePaint.part(&"shadow", s.stage, {}, Rect2(from + UiTokens.D_SHADOW_INSET,
		top + UiTokens.D_H_STAGE_BAR - UiTokens.BORDER_HAIRLINE, to - from - UiTokens.D_SHADOW_INSET, UiTokens.D_H_SHADOW))
	shade.tooltip_text = tr("PRODUCT_STAGE_SHADOW").format({"stage": SprintUiShared.stage_name(s.stage), "before": roundi(s.need_raw),
		"now": roundi(s.need)})
	return shade


## Planlamada kurucunun çalıştığı çubuğun ucunda yüzü; çubuk sığmıyorsa çizilmez.
func _founder_face(entry: Dictionary) -> void:
	var s: Dictionary = entry.stage
	for id: String in s.people:
		if _ctx.people.has(id):
			_faces(entry, [id], true)


## Çubuğa `ids` kişilerinin yüzleri (kurucu halkalı) sağ uca konur ve etiket onlara yer ayırır; çubuk sığmıyorsa yüz çizilmez.
func _faces(entry: Dictionary, ids: Array, planned := false) -> void:
	var faces: HBoxContainer = entry.faces
	UiFactory.clear(faces)
	var bar: StagePaint = entry.ground
	var face_px: int = UiTokens.D_AVATAR_ROW_SM
	var width: float = ids.size() * (face_px - UiTokens.SPACE_S) + UiTokens.SPACE_S
	var text_w: float = StagePaint.text_width(String(entry.main) + String(entry.sub))
	var room: float = 0.0
	var need: float = float(entry.left) + UiTokens.D_ICON_TAG + UiTokens.SPACE_S + text_w + width + UiTokens.SPACE_S + UiTokens.D_STAGE_BAR_PAD.y
	if not ids.is_empty() and bar.size.x >= (need if planned else width + float(entry.left) + UiTokens.D_STAGE_BAR_PAD.y):
		for id: String in ids:
			faces.add_child(SprintUiShared.face(_ctx.people[id], face_px, false, false))
		faces.position = Vector2(bar.size.x - UiTokens.D_STAGE_BAR_PAD.y - width, (bar.size.y - face_px) / 2.0)
		room = width + UiTokens.SPACE_S
	(entry.label as StagePaint).set_bar({"room": room})


func _workers(s: Dictionary) -> Array:
	var out: Array = []
	for id: String in _ctx.people:
		for p: Dictionary in _ctx.people[id].pieces:
			if p.card == card.id and p.stage == s.stage and not p.ahead and p.to > s.start and p.from < s.end:
				out.append({"id": id, "from": p.from, "to": p.to})
	return out


## Koşan sprintte şimdiki an `at` (sprint başından hafta): her çubuğun hâli (biten, sürüyor, bekliyor), dolgusu, yazısı ve o an
## çalışanların yüzleri saklanan parçalardan okunur. Süren çubuk "{yapılan}/{toplam}" yazar (yapılan tamsayıya aşağı yuvarlanır: biten
## çubuk dışında tam görünmez), başlamamış çubuk planlamadaki gibi aşamanın bu eksendeki işini. Süren çubuğun dolgusunun yüzdesi
## (aşağı yuvarlanır) durum yuvasında "{aşama} %{n}" olur.
func set_now(at: float) -> void:
	_now = at
	var stage_pct := ""
	for entry: Dictionary in _live:
		var s: Dictionary = entry.stage
		var total: float = s.pre + s.need
		var made: float = s.pre + SprintTimeline.done_at(s, at)
		var fill: float = clampf(made / total, 0.0, 1.0)
		var state: String = "done" if at >= s.end - SprintSystem.EPS else ("run" if at >= s.start - SprintSystem.EPS else "wait")
		entry.main = entry.work if state == "wait" else str(floori(made + SprintSystem.EPS))
		entry.sub = "" if state == "wait" else "/%d" % roundi(total)
		(entry.ground as StagePaint).set_bar({"state": state, "fill": fill if state == "run" else 0.0})
		(entry.label as StagePaint).set_bar({"state": state, "main": entry.main, "sub": entry.sub})
		var working: Array = []
		if state == "run":
			stage_pct = tr("PRODUCT_STAGE_PCT").format({"stage": SprintUiShared.stage_name(s.stage),
				"pct": Fmt.percent(floorf(fill * 100.0 + SprintSystem.EPS), 0)})
			for w: Dictionary in entry.workers:
				if w.from <= at and at < w.to:
					working.append(w.id)
		_faces(entry, working)
	if not card.late and stage_pct != _stage_pct:
		_stage_pct = stage_pct
		_fill_status()

		await _mount_shot_shell()
		EventBus.tab_changed.emit("product")
		if id == "live:overview_pre" or id.begins_with("live:server"):
			await _product_overview_shot(id.trim_prefix("live:"), stem)
			return
		if id in ["live:pick_named", "live:pick_relang"]:
			var picker: TypePicker = _shell.find_children("*", "TypePicker", true, false)[0]
			picker._pick_type("note_tool")
			picker._name = "Notly"   # LOC-DATA debug seed / name
			picker._save_draft()
		if id.begins_with("live:decision_paper"):
			await get_tree().process_frame
			for row: BoardRow in _shell.find_children("*", "BoardRow", true, false):
				if row.card.ask != null:
					row.action.emit("decide", {"card_id": row.card.id, "item": row.card.ask.item})
					break
			if id != "live:decision_paper":   # a real paper: its answer is open, so its options and their chips are in the frame
				await get_tree().create_timer(0.4).timeout
				_press_button_labelled(_shell, tr("MAIL_RESPOND"))
		if id.begins_with("live:a4_") and not await _product_a4_ready(id.trim_prefix("live:")):
			return
			if cap._rows[i].streak >= 2:
				return cap._tips[i][0]
		return null
	if tip == "next":
		var done: Array = page.find_children("*", "SprintNext", true, false)[0].find_children("*", "StagePaint", true, false).filter(
			func(part: StagePaint) -> bool: return part.kind == &"seg" and part.spec.fill > 0.0)
		return null if done.is_empty() else done[0]
	var rows: Array = page.find_children("*", "BoardRow", true, false).filter(func(row: BoardRow) -> bool: return not row.is_candidate())
	if tip == "bar":
		for row: BoardRow in rows:
			for entry: Dictionary in row._live:
				if entry.ground.spec.state == "run":
					return entry.ground
		return null
	var picks: Dictionary = {"card": func(c: Dictionary) -> bool: return c.slot.get("kind", "") == "due",
		"fix": func(c: Dictionary) -> bool: return c.kind == "fix", "founder": func(c: Dictionary) -> bool: return c.founder,
		"plain": func(c: Dictionary) -> bool: return c.pm == null and not c.stages.is_empty()}
	var picked: Array = rows.filter(func(row: BoardRow) -> bool: return picks[tip].call(row.card))
	if tip == "card" and picked.is_empty():
		picked = rows
	if picked.is_empty():
		return null
